package backoff

import "time"

// Delay returns the wait before retry number attempt (1-based): base * 2^(attempt-1),
// capped at max. It returns 0 for attempt < 1 or non-positive base/max.
func Delay(attempt int, base, max time.Duration) time.Duration {
	if attempt < 1 || base <= 0 || max <= 0 {
		return 0
	}
	d := base
	for i := 1; i < attempt; i++ {
		// Doubling d would exceed max when d > max/2 (integer division is exact here).
		if d > max/2 {
			return max
		}
		d *= 2
	}
	if d > max {
		return max
	}
	return d
}

