package backoff

import (
	"testing"
	"time"
)

func TestCompiles(t *testing.T) {
	_ = Delay
}

func TestDelay(t *testing.T) {
	const ms = time.Millisecond
	tests := []struct {
		name    string
		attempt int
		base    time.Duration
		max     time.Duration
		want    time.Duration
	}{
		{"attempt zero", 0, ms, time.Second, 0},
		{"attempt negative", -3, ms, time.Second, 0},
		{"attempt one is base", 1, ms, time.Second, ms},
		{"attempt two doubles", 2, ms, time.Second, 2 * ms},
		{"attempt three quadruples", 3, ms, time.Second, 4 * ms},
		{"attempt four", 4, ms, time.Second, 8 * ms},
		{"capped at max", 11, ms, 500 * ms, 500 * ms},
		{"exactly max is kept", 4, ms, 8 * ms, 8 * ms},
		{"doubling passes max returns max", 5, ms, 10 * ms, 10 * ms},
		{"base above max returns max", 1, 10 * ms, 5 * ms, 5 * ms},
		{"zero base", 3, 0, time.Second, 0},
		{"negative base", 3, -ms, time.Second, 0},
		{"zero max", 3, ms, 0, 0},
		{"negative max", 3, ms, -ms, 0},
		{"large attempt returns max", 200, ms, time.Minute, time.Minute},
		{"huge attempt does not overflow", 1 << 30, time.Nanosecond, time.Hour, time.Hour},
		{"max near overflow", 100, time.Second, 1<<63 - 1, 1<<63 - 1},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := Delay(tt.attempt, tt.base, tt.max); got != tt.want {
				t.Errorf("Delay(%d, %v, %v) = %v, want %v", tt.attempt, tt.base, tt.max, got, tt.want)
			}
		})
	}
}

func TestDelayNeverExceedsMax(t *testing.T) {
	base, max := 3*time.Millisecond, 100*time.Millisecond
	for attempt := 1; attempt <= 100; attempt++ {
		if got := Delay(attempt, base, max); got > max {
			t.Fatalf("Delay(%d) = %v exceeds max %v", attempt, got, max)
		}
	}
}

